try {
  const message = $node["Telegram Trigger"].json.message;

  if (!message || !message.chat || !message.from) {
    throw new Error("Estrutura da mensagem do Telegram inválida");
  }

  if (!message.chat.id) {
    throw new Error("ID do chat não encontrado na mensagem");
  }

  if (!message.from.id) {
    throw new Error("ID do usuário não encontrado na mensagem");
  }

  let text = '';
  if (message.text) {
    text = message.text.replace('/docimagem', '').trim();
  } else if (message.caption) {
    text = message.caption.replace('/docimagem', '').trim();
  } else {
    throw new Error("Nenhum texto ou legenda encontrado na mensagem");
  }

  if (text.length === 0) {
    throw new Error("O texto para inserir no documento está vazio. Por favor, envie algum texto após o comando /docimagem");
  }

  if (text.length > 5000) {
    throw new Error("Texto muito longo (máximo 5000 caracteres). Por favor, divida seu conteúdo em partes menores");
  }

  const problematicChars = /[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g;
  if (problematicChars.test(text)) {
    text = text.replace(problematicChars, '');
  }

  let photoId = null;
  if (message.photo && Array.isArray(message.photo) && message.photo.length > 0) {
    const photo = message.photo[message.photo.length - 1];
    if (photo && photo.file_id) {
      photoId = photo.file_id;
    }
  }

  if (!photoId) {
    throw new Error("Nenhuma imagem encontrada na mensagem. Por favor, envie uma imagem com o comando /docimagem");
  }

  if (typeof photoId !== 'string' || photoId.trim() === '') {
    throw new Error("ID da foto inválido obtido do Telegram");
  }

  const photo = message.photo[message.photo.length - 1];
  if (photo.file_size && photo.file_size > 20 * 1024 * 1024) { // 20MB
    throw new Error("Imagem muito grande (máximo 20MB). Por favor, envie uma imagem menor");
  }

  return {
    chatId: message.chat.id,
    userId: message.from.id,
    textToInject: text,
    photoId: photoId,
    success: true,
    userName: message.from.first_name || 'Usuário',
    userUsername: message.from.username || 'sem_username'
  };

} catch (error) {
  console.error('Erro na extração de dados /docimagem:', error);

  let fallbackChatId = null;
  try {
    const message = $node["Telegram Trigger"].json.message;
    if (message && message.chat && message.chat.id) {
      fallbackChatId = message.chat.id;
    }
  } catch (fallbackError) {
    console.error('Erro ao obter chat ID de fallback:', fallbackError);
  }

  return {
    chatId: fallbackChatId,
    error: true,
    errorMessage: error.message,
    success: false
  };
}

try {
  const message = $node["Telegram Trigger"].json.message;

  if (!message) {
    throw new Error("Mensagem do Telegram não recebida ou formato inválido");
  }

  if (!message.chat || !message.chat.id) {
    throw new Error("ID do chat não encontrado na mensagem");
  }

  if (!message.from || !message.from.id) {
    throw new Error("ID do usuário não encontrado na mensagem");
  }

  if (!message.text) {
    throw new Error("Por favor, envie o comando no formato: /criardocumento [seu texto aqui]");
  }

  let text = message.text.replace('/criardocumento', '').trim();

  if (text.length === 0) {
    throw new Error("O texto não pode estar vazio. Por favor, envie no formato:\n/criardocumento [seu texto aqui]");
  }

  if (text.length > 2000) {
    throw new Error("Texto muito longo (máximo 2000 caracteres). Por favor, divida seu conteúdo em partes menores");
  }

  const invalidChars = /[<>{}[\]]/g;
  if (invalidChars.test(text)) {
    throw new Error("O texto contém caracteres inválidos (<, >, {, }, [, ]). Por favor, remova-os");
  }

  const controlChars = /[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g;
  if (controlChars.test(text)) {
    text = text.replace(controlChars, '');
  }

  if (text.replace(/[\s\n\r\t]/g, '').length === 0) {
    throw new Error("O texto não pode conter apenas espaços em branco. Por favor, adicione conteúdo válido");
  }

  return {
    chatId: message.chat.id,
    userId: message.from.id,
    textToInject: text,
    success: true,
    userName: message.from.first_name || 'Usuário',
    userUsername: message.from.username || 'sem_username'
