const html = $input.first().json.data;
const noticias = [];

// Função para extrair links e títulos usando regex
function extrairNoticias(html, selectores) {
  const resultados = [];

  for (const seletor of selectores) {
    // Padrão regex para encontrar elementos <a> com a classe especificada
    const regex = new RegExp(`<a[^>]*class=["'][^"']*${seletor}[^"']*["'][^>]*href=["']([^"']+)["'][^>]*>([\\s\\S]*?)<\\/a>`, 'gi');
    let match;

    while ((match = regex.exec(html)) !== null && resultados.length < 10) {
      const link = match[1].trim();
      let titulo = match[2].replace(/<[^>]+>/g, '').trim(); // Remove tags HTML dentro do título

      if (titulo && link && titulo.length > 10) {
        let fullLink = link;
        if (link.startsWith('/')) {
          fullLink = 'https://g1.globo.com' + link;
        }

        resultados.push({
          titulo: titulo,
          link: fullLink
        });
      }
    }

    if (resultados.length >= 10) break;
  }

  return resultados;
}

// Primeira tentativa com seletores principais
noticias.push(...extrairNoticias(html, [
  'feed-post-link',
  'bastian-feed-item',
  'bstn-fd-relatedLink'
]));

// Segunda tentativa com seletores alternativos se não encontrou nada
if (noticias.length === 0) {
  noticias.push(...extrairNoticias(html, [
    'feed-post-body-title',
    'content-head__title'
  ]));
}

return [{ json: { noticias: noticias.slice(0, 10) } }];

